fn target_name(date: &str, original: &Path) -> Option<PathBuf> {
    let ext = original.extension()?.to_str()?;
    Some(PathBuf::from(format!("{date}.{ext}")))
}

/// Borda: lê a data do arquivo (EXIF ou mtime). Aqui entra o IO.
